noncomputable def ofRat {n : ℕ} {c : Fin n → complexLorentzTensor.C}
    (f : (Π j, Fin (complexLorentzTensor.repDim (c j))) → RatComplexNum) :
    complexLorentzTensor.F.obj (OverColor.mk c)

lemma ofRat_add {n : ℕ} {c : Fin n → complexLorentzTensor.C}
    (f f1 : (Π j, Fin (complexLorentzTensor.repDim (c j))) → RatComplexNum) :
    ofRat (f + f1) = ofRat f + ofRat f1

lemma contr_ofRat {n : ℕ} {c : Fin (n + 1 + 1) → complexLorentzTensor.C} {i : Fin (n + 1 + 1)}
    {j : Fin (n + 1)} {h : c (i.succAbove j) = complexLorentzTensor.τ (c i)}
    (f : (Π k, Fin (complexLorentzTensor.repDim (c k))) → RatComplexNum) :
  (contr i j h (tensorNode (ofRat f))).tensor = (tensorNode (ofRat (fun b =>
    (∑ x : { x // x ∈ TensorSpecies.TensorBasis.ContrSection b },
      f x.1 * if (x.1 i).1 = (x.1 (i.succAbove j)).1 then 1 else 0)))).tensor

lemma perm_ofRat {n m : ℕ} {c : Fin n → complexLorentzTensor.C}
    {c1 : Fin m → complexLorentzTensor.C}
    {σ : (OverColor.mk c) ⟶ (OverColor.mk c1)}
    (f : (Π j, Fin (complexLorentzTensor.repDim (c j))) → RatComplexNum) :
    (perm σ (tensorNode (ofRat f))).tensor =
    (tensorNode (ofRat (fun b => f ((TensorSpecies.TensorBasis.congr (Hom.toEquiv σ)
    (OverColor.Hom.toEquiv_comp_apply σ)) b)))).tensor

def liftTensor {n : ℕ} {c : Fin n → S.C} {E : Type} [AddCommMonoid E] [Module S.k E]:
    MultilinearMap S.k (fun i => S.FD.obj (Discrete.mk (c i))) E ≃ₗ[S.k]
    (S.F.obj (OverColor.mk c) →ₗ[S.k] E)

def coordinateMultiLinear {n : ℕ} (c : Fin n → S.C) :
    MultilinearMap S.k (fun i => S.FD.obj (Discrete.mk (c i)))
    ((Π j, Fin (S.repDim (c j))) → S.k) where

def congr {n m : ℕ} {c : Fin n → S.C} {c1 : Fin m → S.C}
    (σ : Fin n ≃ Fin m) (h : ∀ i, c i = c1 (σ i)) :
    (Π j, Fin (S.repDim (c1 j))) ≃ Π j, Fin (S.repDim (c j)) where

def elimEquiv {n m : ℕ} {c : Fin n → S.C} {c1 : Fin m → S.C} :
    (Π j, Fin (S.repDim (Sum.elim c c1 j))) ≃
    (Π j, Fin (S.repDim (c j))) × (Π j, Fin (S.repDim (c1 j))) where

def prodEquiv {n m : ℕ} {c : Fin n → S.C} {c1 : Fin m → S.C} :
    (Π j, Fin (S.repDim (Sum.elim c c1 (finSumFinEquiv.symm j)))) ≃
    (Π j, Fin (S.repDim (c j))) × (Π j, Fin (S.repDim (c1 j)))

def ContrSection {n : ℕ} {c : Fin n.succ.succ → S.C}
    {i : Fin n.succ.succ} {j : Fin n.succ}
    (b : Π k, Fin (S.repDim ((c ∘ i.succAbove ∘ j.succAbove) k))) :
    Finset (Π k, Fin (S.repDim (c k)))

noncomputable def tensorOfInt {n : ℕ} {c : Fin n → S.C}
    (f : (Π j, Fin (S.repDim (c j))) → ℤ) :
    S.F.obj (OverColor.mk c)
